INSERT INTO bookmarks (id, url, title, domain, description, note) VALUES (1, 'https://github.com/zumerlab/snapdom', 'SnapDOM', 'github.com', 'snapDOM is a fast and accurate DOM-to-image capture tool. It converts any HTML element into a scalable SVG image, preserving styles, fonts, background images and pseudo-elements.', 'Possible replacement for html2canvas in the screenshot feature.');
INSERT INTO bookmarks (id, url, title, domain, description, note) VALUES (2, 'https://squoosh.app/', 'Squoosh', 'squoosh.app', 'Make images smaller using best-in-class codecs, right in the browser.', 'Compare AVIF and WebP output side by side.');
INSERT INTO bookmarks (id, url, title, domain, description, note) VALUES (3, 'https://date-fns.org/', 'date-fns - modern JavaScript date utility library', 'date-fns.org', 'date-fns provides the most comprehensive yet simple and consistent toolset for manipulating JavaScript dates in a browser and Node.js.', 'Use format() for display dates.');
