INSERT INTO bookmarks (id, url, title, domain, description, note) VALUES (6, 'https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_containment/Container_queries', 'CSS container queries - CSS | MDN', 'developer.mozilla.org', 'Container queries enable you to apply styles to an element based on certain attributes of its container.', 'Good intro with size and style queries.');
