INSERT INTO bookmarks (id, url, title, domain, description, note) VALUES (12, 'https://stackoverflow.com/questions/927358/how-do-i-undo-the-most-recent-local-commits-in-git', 'How do I undo the most recent local commits in Git?', 'stackoverflow.com', 'I accidentally committed the wrong files to Git, but didn''t push the commit to the server yet. How do I undo those commits from the local repository?', 'git reset --soft HEAD~1');
